Recipe: find-and-update-component
Find a component by type in the page content tree, then update one of its properties. Handles nested component tree navigation automatically. Uses numeric indexes for JSON Patch paths.
Parameters: pageId, componentType, propertyName, newValue
```js
// Step 1: Read page content
const page = await aem.get('/adobe/experimental/aspm-expires-20251231/pages/' + pageId + '/content');
const content = page.body;

// Step 2: Navigate tree to find component by type
// items is an array — use numeric indexes for JSON Patch paths.
// Path segments: /items/<index> where index is the array position.
function findComponent(node, type, path) {
  if (node.componentType && node.componentType.includes(type)) {
    return { node, path };
  }
  if (Array.isArray(node.items)) {
    for (let i = 0; i < node.items.length; i++) {
      const found = findComponent(node.items[i], type, path + '/items/' + i);
      if (found) return found;
    }
  }
  return null;
}

const found = findComponent(content, componentType, '');
if (!found) return { error: 'Component type not found: ' + componentType };

// Step 3: Patch the property
const patchPath = found.path + '/properties/' + propertyName;
const patch = [{ op: 'replace', path: patchPath, value: newValue }];
const result = await aem.patch('/adobe/experimental/aspm-expires-20251231/pages/' + pageId + '/content', patch, page.etag);
return { updated: patchPath, result };
```

Recipe: add-component-to-page
Add a new component to a page's content tree via JSON Patch, validated against the page's content-definition. Appends into a container's items array using '/items/-' — every 'items' path segment is a NUMERIC index; a component name is never a valid path segment (returns 400). Reads the content-definition to (a) confirm the componentType is allowed in the target container (placement rules) and (b) fill any mandatory properties, so the add does not fail with an opaque 400.
Parameters: pageId, containerPath, componentType, properties
```js
const base = '/adobe/experimental/aspm-expires-20251231/pages';

// Step 1: current content (ARRAY tree) for the ETag + to locate the container. Each node carries
// capi-key/capi-index — use them to build the numeric containerPath (capi-key '0:1' -> '/items/0/items/1').
const page = await aem.get(base + '/' + pageId + '/content');

// Step 2: content-definition — used to validate placement and fill mandatory props.
// aem.get returns { status, body, etag } and does NOT throw on 4xx; branch on status. If the
// definition is unavailable, proceed without validation rather than aborting.
const defRes = await aem.get(base + '/' + pageId + '/content/definition');
const def = defRes.status === 200 ? defRes.body : null;

// short ref of a componentType, e.g. core/franklin/components/section/v1/section -> section
const refOf = (ct) => { const m = (ct || '').match(/components\/([^\/]+)\//); return m ? m[1] : ct; };
// navigate to the container node at containerPath (numeric /items/<i> segments)
function nodeAt(root, p) { let n = root; for (const seg of (p || '').split('/items/').filter(Boolean)) { n = (n.items || [])[parseInt(seg, 10)]; if (!n) return null; } return n; }

const container = containerPath ? nodeAt(page.body, containerPath) : page.body;
if (!container) return { error: 'containerPath not found: ' + containerPath };

// Step 3: validate placement + gather mandatory properties from the definition.
let mandatory = {};
if (def && Array.isArray(def.placementRules)) {
  const cref = refOf(container.componentType);
  const rule = def.placementRules.find(r => (((r.condition || {}).matchTarget || {}).componentDefinitionRef) === cref);
  const allowed = rule ? (rule.action.allowedInsertions || []) : [];
  const ins = allowed.find(a => a.componentDefinitionRef === refOf(componentType));
  if (allowed.length && !ins) {
    return { error: componentType + ' is not allowed in this container (' + cref + ')', allowed: Array.from(new Set(allowed.map(a => a.componentDefinitionRef))) };
  }
  if (ins && ins.mandatoryProperties) mandatory = ins.mandatoryProperties;
}

// Step 4: append with '/items/-' (or a numeric index to insert at a position). The value's
// properties use the definition's field names; nested children go in an `items` ARRAY.
const patch = [{
  op: 'add',
  path: containerPath + '/items/-',
  value: { componentType: componentType, properties: Object.assign({}, mandatory, properties || {}), items: [] }
}];
const result = await aem.patch(base + '/' + pageId + '/content', patch, page.etag);
return result;
```

Recipe: search-pages-by-component-type
Find pages containing a given component (sling:resourceType) using the page-search endpoint.
Parameters: componentType, matchMode, publishStatus, siteId, parentPageId, limit, cursor
```js
// Build the search body — omit undefined fields
const searchBody = { componentType: componentType };
if (matchMode) searchBody.matchMode = matchMode;
if (publishStatus) searchBody.publishStatus = publishStatus;
if (siteId) searchBody.siteId = siteId;
if (parentPageId) searchBody.parentPageId = parentPageId;
searchBody.limit = limit || 50;
if (cursor) searchBody.cursor = cursor;

const result = await aem.post(
  '/adobe/experimental/aspm-expires-20251231/pages/search',
  searchBody
);
return { items: result.body.items || [], cursor: result.body.cursor };
```

Recipe: replace-page-content
Replace the entire page content tree (PUT) with ETag — use sparingly; prefer PATCH (find-and-update-component) when modifying individual fields.
Parameters: pageId, eTag, content
```js
// PUT replaces the entire content tree — all existing fields are overwritten.
// Always read the current content first to get a valid ETag.
const result = await aem.put(
  '/adobe/experimental/aspm-expires-20251231/pages/' + pageId + '/content',
  content,
  eTag
);
if (result.status === 412) {
  return { error: 'ETag conflict (412): the page was modified since you last read it. Re-read the page to get the current ETag and retry.' };
}
return { pageId, newEtag: result.etag, body: result.body };
```

Recipe: bulk-find-replace-pages-in-launch
Safe staging variant: create a launch over candidate pages, apply find-replace inside the launch, return diff URLs for review. Discovers the pages to stage automatically — by explicit authorPaths if given, else by componentType (component-usage search), else by full-text keyword search on the `find` text (search-temporary) — so a plain "replace X with Y across the site" works without the caller pre-supplying paths. On ANY step failure it stops and reports; it never falls back to per-page raw edits.
Parameters: find, replace, caseSensitive, launchTitle, componentType, authorPaths, matchMode, tags, publishStatus, siteId
```js
// Step 1: Determine the candidate authorPaths to stage in the launch.
// All discovery uses the CONTENT-API base path (/adobe/experimental/aspm-expires-20251231/...),
// which is DIFFERENT from the launch custom-endpoint base path used in Step 2
// (/adobe/experimental/aemmcpserver-expires-20991231/...). Do not conflate the two.
// Priority: explicit authorPaths > component search > full-text keyword search on `find`.
let paths = authorPaths ? authorPaths.slice() : [];
if (paths.length === 0 && componentType) {
  // 1a. Component-usage search (pages containing a given sling:resourceType).
  let cur = undefined;
  do {
    const searchBody = { componentType: componentType, limit: 50 };
    if (matchMode) searchBody.matchMode = matchMode;
    if (publishStatus) searchBody.publishStatus = publishStatus;
    if (siteId) searchBody.siteId = siteId;
    if (cur) searchBody.cursor = cur;
    const r = await aem.post('/adobe/experimental/aspm-expires-20251231/pages/search', searchBody);
    if (r.status < 200 || r.status >= 300) {
      return { error: 'Page component search failed — STOP and report; no launch created.', status: r.status, detail: r.body };
    }
    for (const item of r.body.items || []) {
      if (item.authorPath) paths.push(item.authorPath);
    }
    cur = r.body.cursor;
  } while (cur);
} else if (paths.length === 0) {
  // 1b. Full-text keyword discovery: the pages to edit are the pages that CONTAIN the find
  // text, so query the full-text endpoint (search-temporary) with q = find. It returns
  // items[].authorPath — the JCR author path needed for the launch's srcPathList. This is the
  // discovery step that makes a text-based "replace X with Y across the site" work in launch
  // mode (component search alone cannot find pages by arbitrary text).
  // Caveat: search-temporary matches page metadata + indexed content; text that lives only in
  // a referenced Content Fragment may not match — pass authorPaths explicitly for those cases.
  let cur = undefined;
  do {
    const params = { q: find, limit: 50 };
    if (siteId) params.siteId = siteId;
    if (cur) params.cursor = cur;
    const r = await aem.get('/adobe/experimental/aspm-expires-20251231/pages/search-temporary', params);
    if (r.status < 200 || r.status >= 300) {
      return { error: 'Page keyword search failed — STOP and report; no launch created.', status: r.status, detail: r.body };
    }
    for (const item of r.body.items || []) {
      if (item.authorPath) paths.push(item.authorPath);
    }
    cur = r.body.cursor;
  } while (cur);
}
if (paths.length === 0) return { error: 'No pages found matching the provided criteria. No launch was created.' };

// Step 2: Create a launch containing all candidate pages
const effectiveTitle = launchTitle || ('Bulk find-replace: ' + find + ' → ' + replace);
// NOTE: launch creation uses the CUSTOM-ENDPOINT base path
// (/adobe/experimental/aemmcpserver-expires-20991231/...), NOT the content-API path used for
// search/findReplace. These are two distinct routing prefixes — do not mix them.
const launched = await aem.post(
  '/adobe/experimental/aemmcpserver-expires-20991231/launches',
  {
    title: effectiveTitle,
    srcPathList: paths,
    shallowList: paths.map(function() { return true; })
  }
);
if (launched.status < 200 || launched.status >= 300) {
  return { error: 'Launch creation failed — STOP and report; no bulk edit attempted.', status: launched.status, detail: launched.body };
}
const launchPagePath = launched.body.path;
if (!launchPagePath) return { error: 'Launch creation did not return a path.', response: launched.body };

// Step 3: Derive the launch root (everything before the second /content/ occurrence after the /content/launches/ prefix)
const secondContentIndex = launchPagePath.indexOf('/content/', launchPagePath.indexOf('/content/launches/') + 1);
let launchRoot;
if (secondContentIndex !== -1) {
  launchRoot = launchPagePath.substring(0, secondContentIndex);
} else {
  const launchPathMatch = launchPagePath.match(/^(\/content\/launches\/[^/]+\/[^/]+\/[^/]+)/);
  launchRoot = launchPathMatch ? launchPathMatch[1] : launchPagePath;
}

// Step 4: Compute launch-scoped paths
const launchAuthorPaths = paths.map(function(p) { return launchRoot + p; });

// Step 5: Apply find-replace inside the launch
const frBody = { find: find, replace: replace, authorPaths: launchAuthorPaths };
if (caseSensitive !== undefined) frBody.caseSensitive = caseSensitive;
const frResult = await aem.post(
  '/adobe/experimental/aspm-expires-20251231/pages/content/findReplace',
  frBody
);
if (frResult.status < 200 || frResult.status >= 300) {
  // FAIL LOUD: report the failure to the user; do NOT fall back to editing pages one-by-one
  // via read-api/write-api — that bypasses the launch-safety model. The launch exists but was
  // not modified; the user can discard it with delete-page-launch.
  return {
    error: 'Bulk find/replace failed inside the launch. STOP and report this to the user; do NOT edit pages individually as a workaround.',
    status: frResult.status,
    detail: frResult.body,
    launchRoot: launchRoot,
    cleanup: 'delete-page-launch on the created launch'
  };
}

return {
  launchTitle: effectiveTitle,
  launchRoot: launchRoot,
  totalReplacementCount: frResult.body.totalReplacementCount,
  pagesModified: frResult.body.pagesModified,
  modifiedPages: (frResult.body.items || []).map(function(i) { return i.launchPagePath || i.path; }),
  nextSteps: {
    approve: 'use promote-page-launch on the launch',
    reject: 'use delete-page-launch'
  }
};
```

Recipe: render-fragment-with-template
Discover templates for a model, pick one by name, and render a fragment using it.
Parameters: modelId, templateName, fragmentId, variation
```js
// Step 1: List templates for the model to find the templateId by name
const list = await aem.get('/adobe/contentFragments/models/' + modelId + '/templates', {
  limit: '50'
});
const items = list.body.items || [];
const match = items.find(function(t) { return t.name === templateName; });
if (!match) {
  return {
    error: 'Template not found: ' + templateName,
    available: items.map(function(t) { return t.name; })
  };
}

// Step 2: Render the fragment with the matched templateId
const params = { templateId: match.id };
if (variation) params.variation = variation;
const preview = await aem.get(
  '/adobe/contentFragments/' + fragmentId + '/preview',
  params
);
// preview.body is raw HTML text (text/html response)
return { html: preview.body, templateId: match.id };
```

Recipe: patch-fragment-with-references
Patch a fragment after discovering all referenced fragments (advisory: patch is applied to the main fragment only; references are reported for review).
Parameters: fragmentId, ifMatch, patchOperations
```js
// Step 1: Discover the full dependency tree
const withRefs = await aem.get('/adobe/sites/cf/fragments/' + fragmentId, { references: 'all-hydrated' });
const references = withRefs.body.references || [];

// Step 2: Patch the main fragment only
const patched = await aem.patch(
  '/adobe/sites/cf/fragments/' + fragmentId,
  patchOperations,
  ifMatch
);

return {
  patched: fragmentId,
  references: references.map(function(r) { return { id: r.id, title: r.title, path: r.path }; }),
  note: 'Patch applied to main fragment only. Review referenced fragments above before patching them individually.',
  body: patched.body
};
```

Recipe: full-template-lifecycle
Create a template, render a fragment preview with it, update the template, and clean up.
Parameters: modelId, fragmentId, templateName, initialContent, updatedContent
```js
// Step 1: Validate and create
const created = await aem.post(
  '/adobe/contentFragments/models/' + modelId + '/templates?dryRun=true',
  { name: templateName, content: initialContent }
);
if (created.status !== 204) return { error: 'Validation failed', details: created.body };

const template = await aem.post(
  '/adobe/contentFragments/models/' + modelId + '/templates',
  { name: templateName, content: initialContent }
);
const templateId = template.body.id;

// Step 2: Render a preview using the new template
const preview = await aem.get(
  '/adobe/contentFragments/' + fragmentId + '/preview',
  { templateId: templateId }
);
// preview.body is raw HTML

// Step 3: Update the template content
const getResp = await aem.get(
  '/adobe/contentFragments/models/' + modelId + '/templates/' + templateId
);
await aem.put(
  '/adobe/contentFragments/models/' + modelId + '/templates/' + templateId,
  { content: updatedContent },
  getResp.etag
);

// Step 4: Re-render to confirm the update is reflected
const updatedPreview = await aem.get(
  '/adobe/contentFragments/' + fragmentId + '/preview',
  { templateId: templateId }
);

return {
  templateId: templateId,
  initialHtml: preview.body,
  updatedHtml: updatedPreview.body
};
```

Recipe: check-fragment-impact
Find all resources (pages and fragments) that reference a given fragment before deleting or modifying it, with cursor-based pagination.
Parameters: fragmentId, limit, cursor
```js
// Fetch incoming references — who links TO this fragment
const params = { limit: String(limit || 10) };
if (cursor) params.cursor = cursor;

const result = await aem.get('/adobe/sites/cf/fragments/' + fragmentId + '/referencedBy', params);
const items = result.body.items || [];
const nextCursor = result.body.cursor;

return {
  fragmentId: fragmentId,
  referenceCount: items.length,
  items: items,
  nextCursor: nextCursor || null,
  note: items.length === 0
    ? 'No resources reference this fragment — safe to delete.'
    : 'Fragment is referenced by ' + items.length + ' resource(s). Review before deleting.'
};
```

